DROP TABLE IF EXISTS `county_temperature`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `county_temperature` (
  `fips` char(10) NOT NULL COMMENT 'County FIPS code (Primary Key)',
  `county_name` varchar(100) NOT NULL COMMENT 'County name',
  `year` int NOT NULL COMMENT 'Year (1895–2019)',
  `temp` float NOT NULL COMMENT 'Average temperature (°F)',
  `tempc` float NOT NULL COMMENT 'Average temperature (°C)',
  PRIMARY KEY (`fips`,`year`),
  KEY `idx_county_temp_year` (`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='County-level annual temperature';
